import{_ as t,o as a,c as r,a4 as _}from"./chunks/framework.C3unmAF4.js";const h=JSON.parse('{"title":"“人工智能+农业”抢占“智”高点","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"“人工智能+农业”抢占“智”高点","date":"2026-08-07T00:00:00.000Z","source":"中国农业信息网","category":"news","link":"https://www.agri.cn/xxh/zhny/202608/t20260807_8862478.htm","summary":"近日，在杭州召开的以“数智兴农 共创未来”为主题的第四届长三角智慧农业发展大会，集中展示长三角地区及全国智慧农业领域的新技术、新产业、新装备、新模式，从智能传感设备、农业机器人到AI决策系统，多项前沿成果吸引与会代表驻足体验。\\n...\\n","contentHash":"28f96864d05bf4747b8a9033d402431d","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-08-07-人工智能-农业-抢占-智-高点.md","filePath":"news/2026-08-07-人工智能-农业-抢占-智-高点.md"}'),n={name:"news/2026-08-07-人工智能-农业-抢占-智-高点.md"};function s(p,e,o,l,i,c){return a(),r("div",null,[...e[0]||(e[0]=[_('<h1 id="人工智能-农业-抢占-智-高点" tabindex="-1">“人工智能+农业”抢占“智”高点 <a class="header-anchor" href="#人工智能-农业-抢占-智-高点" aria-label="Permalink to &quot;“人工智能+农业”抢占“智”高点&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.agri.cn/xxh/zhny/202608/t20260807_8862478.htm" target="_blank" rel="noreferrer">中国农业信息网</a><br> 日期: 2026-08-07 摘要: 近日，在杭州召开的以“数智兴农 共创未来”为主题的第四届长三角智慧农业发展大会，集中展示长三角地区及全国智慧农业领域的新技术、新产业、新装备、新模式，从智能传感设备、农业机器人到AI决策系统，多项前沿成果吸引与会代表驻足体验。 ...</p></blockquote><p>近日，在杭州召开的以“数智兴农 共创未来”为主题的第四届长三角智慧农业发展大会，集中展示长三角地区及全国智慧农业领域的新技术、新产业、新装备、新模式，从智能传感设备、农业机器人到AI决策系统，多项前沿成果吸引与会代表驻足体验。</p><p>从国务院印发《加快农业农村现代化“十五五”规划》，首次将“人工智能+农业”专项行动列入培育农业新质生产力的顶层布局，到《全国智慧农业行动计划（2024—2028年）》落地，人工智能成为保障粮食安全、破解资源瓶颈的“必答题”，需要我们更多地思考如何让AI技术真正扎根泥土，推进人工智能赋能农业农村高质量发展。</p><p>协同攻坚，让AI读懂浙江的“一方水土”。大模型技术正引领新一代人工智能发展，但农业并非标准化车间，再聪明的算法，若不懂具体的农艺和土壤特性，也只能“纸上谈农”。</p><p>浙江的破局之道在于“产学研用”的深度融合，让算法去适应土地，而非让土地妥协于算法。以我省近期落地的“浙里良田”智能体为例，它并未追求泛化的“全知全能”，而是深耕高标准农田的“建、管、用”场景。其背后是450万组土壤改良与培肥试验、1200万条测土配方施肥数据等海量浙江本土基础数据，经大模型训练后，能在智能选址、土壤诊断等环节提供精确决策。同样，面向杨梅特色产业的“知梅”智能体，根据本地环境生成精准的修剪、水肥管理方案。实践证明，只有把浙江的农业数据优势转化为模型优势，通过“产业出题、科研答题”，才能让AI真正掌握浙江的农情、懂得浙江的农事。</p><p>算好经济账，让“黑科技”飞入农户家。AI技术再前沿，成本上“算不过账”，就难以逃离示范园的围墙。</p><p>降低门槛的破冰之举，在浙江已有生动实践。金华市金东区的“低空+AI”农事服务中心，采取“政府搭台、企业运营”的方式，整合50余项AI模型能力，规模化运作后，无人机飞行成本下降80%；在遂昌，农户只需在手机上轻点小程序下单“代耕代种”，就能按亩、按次共享适配梯田的智能农机，据当地测算，仅插秧一项，每亩就能节省60至80元。究其根本，农业AI的生机，在于把“买重装备”变成“买轻服务”，通过“监测+处方+作业+反馈”的闭环，让AI变成农事服务中心提供的一项普惠型“农具”。只有经济上划算，AI才能真正被农民接纳。</p><p>从“盆景”到“风景”，把技术红利留在田间地头。截至目前，浙江已累计建成数字农业工厂729家、未来农场63家，基础扎实、样板丰富。从“样板领先”迈向“普惠领先”，重点应关注有多少中小经营主体从中受益、有多少解决方案被稳定复用。</p><p>一方面，要把公共数据和基础模型做成低成本底座，依托覆盖全省的农事服务网络，让合作社和服务中心成为技术下田的“接口”，避免重复建设和信息孤岛；另一方面，要特别保护农民的数据权益，防止数字化能力的差距演变为新的发展差距。只有这样，智慧农业的“盆景”，才能真正变成广袤田野里触手可及的“风景”。</p><p>从顶层设计到垂直深耕，“人工智能+农业”正迎来最好的发展窗口。尊重农业规律，让数据下田、技术下沉、服务普惠，这股AI浪潮就能沉淀为田野里持续领跑的先发优势。（农村信息报记者 张雅萌）</p><p><a href="https://www.agri.cn/xxh/zhny/202608/t20260807_8862478.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',12)])])}const f=t(n,[["render",s]]);export{h as __pageData,f as default};
